            args=[str(self.session_file), "--corrections-only"]
        )

        bash_lines = set(bash_stdout.strip().split("\n")) if bash_stdout.strip() else set()
        python_lines = set(python_stdout.strip().split("\n")) if python_stdout.strip() else set()

