    const { ClaudeAdapter } = await import('../agents/claude.js')
    const adapter = new ClaudeAdapter(tmpDir)
    expect(adapter.skillDir('my-skill')).toBe(path.join(tmpDir, '.claude', 'skills', 'my-skill'))
